-- FUNCTION: admin_reveal_listing_seller(uuid)
CREATE FUNCTION staging.admin_reveal_listing_seller(p_item_id uuid) RETURNS TABLE(id uuid, name text, email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'staging'
    AS $$
  SELECT pr.id, pr.name::TEXT, pr.email::TEXT
  FROM staging.marketplace_items AS mi
  JOIN staging.profiles AS pr ON pr.id = mi.seller_id
  WHERE mi.id = p_item_id
    AND staging.is_admin();
$$;

-- FUNCTION: admin_reveal_post_author(uuid)
CREATE FUNCTION staging.admin_reveal_post_author(p_post_id uuid) RETURNS TABLE(id uuid, name text, email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'staging'
    AS $$
  SELECT pr.id, pr.name::TEXT, pr.email::TEXT
  FROM staging.posts AS po
  JOIN staging.profiles AS pr ON pr.id = po.author_id
  WHERE po.id = p_post_id
    AND staging.is_admin();
$$;

-- FUNCTION: increment_marketplace_views(uuid)
CREATE FUNCTION staging.increment_marketplace_views(item_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'staging'
    AS $$
  UPDATE staging.marketplace_items SET views = views + 1 WHERE id = item_id;
$$;

-- FUNCTION: is_admin()
CREATE FUNCTION staging.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'staging'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM staging.profiles
    WHERE id = auth.uid() AND role = 'Administrator'
  );
$$;

-- FUNCTION: is_school_email(text)
CREATE FUNCTION staging.is_school_email(p_email text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT lower(split_part(coalesce(p_email, ''), '@', 2))
         ~ '(\.edu|\.edu\.[a-z]{2,}|\.ac\.[a-z]{2,})$'
$_$;

-- FUNCTION: my_conversation_ids()
CREATE FUNCTION staging.my_conversation_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'staging'
    AS $$
  SELECT conversation_id
  FROM   staging.conversation_participants
  WHERE  user_id = auth.uid();
$$;

-- FUNCTION: set_profile_initial_status()
CREATE FUNCTION staging.set_profile_initial_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'staging'
    AS $$
BEGIN
  IF staging.is_school_email(NEW.email) THEN
    NEW.status   := 'approved';
    NEW.verified := true;
  ELSE
    NEW.status   := 'pending';
    NEW.verified := false;
  END IF;
  RETURN NEW;
END;
$$;


