-- ---------- 20261120000000_security_hotfix.sql ----------
-- =============================================================
-- Security hotfix (audit 2026-11-22). Standalone and idempotent:
-- safe to run on its own in the SQL editor before the 20261121 batch,
-- and safe to re-run.
--
--   1. Privilege escalation: any signed-in user could make themselves
--      an Administrator, either by updating their own profile row
--      (the UPDATE policy has no column limits) or by signing up with
--      role = 'Administrator' in the auth metadata (handle_new_user
--      copies it). Admins can call admin_reveal_* and see real
--      identities, so this also breaks anonymity.
--      -> trigger that stops non-admins changing role (to/from
--         Administrator), status, verified or email, and that never
--         lets a new profile start as an approved Administrator.
--   2. profiles: drop the "authenticated users can view all profiles"
--      policy if it exists (lets every member read real names and
--      emails). Own-row and admin policies stay.
--   3. Anonymous visitors (anon key, not signed in) could read posts,
--      comments, likes, marketplace listings (incl. contact and
--      location) and saves on production, because of policies that are
--      not in this repo. The app only loads data after sign-in, so
--      anon needs no table access at all.
--      -> revoke table privileges from anon. RPCs used before sign-in
--         (get_email_by_username, is_school_email) are functions and
--         are not affected.
--   4. _backup_20261024_* tables (base64 image copies) were publicly
--      readable. Same lock-down as 20261121000300, applied early.
--
--   5. Impersonation: on production, INSERT policies on posts,
--      post_comments and post_likes have WITH CHECK (true), so a member
--      could post, comment or like under another member's id. Profiles
--      has an "Enable insert for authenticated users" WITH CHECK (true).
--      -> RESTRICTIVE insert policies requiring the owner column to be
--         auth.uid() on every user-content table. Restrictive policies
--         apply on top of whatever permissive ones exist, so this works
--         without knowing every drifted policy name.
--
-- Not changed here (needs a product decision): get_email_by_username
-- lets anyone turn a username into an email address.
-- =============================================================

CREATE SCHEMA IF NOT EXISTS staging_private;
REVOKE ALL ON SCHEMA staging_private FROM PUBLIC;

-- 1. Profile privilege guard -----------------------------------------
CREATE OR REPLACE FUNCTION staging_private.guard_profile_privileges()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = staging
AS $$
BEGIN
  -- Client requests run with role anon/authenticated (PostgREST sets it;
  -- SECURITY DEFINER doesn't change it). Inside handle_new_user, fired by
  -- an auth.users insert, we're one trigger level deeper and the values
  -- come straight from user-controlled signup metadata.
  IF TG_OP = 'INSERT' THEN
    IF pg_trigger_depth() > 1
       OR current_setting('role', true) IN ('anon', 'authenticated') THEN
      IF NEW.role = 'Administrator' THEN
        NEW.role := 'Current Student';
      END IF;
      NEW.status := 'pending';
      NEW.verified := false;
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  IF current_setting('role', true) IN ('anon', 'authenticated')
     AND NOT staging.is_admin() THEN
    IF NEW.role IS DISTINCT FROM OLD.role
       AND (NEW.role = 'Administrator' OR OLD.role = 'Administrator') THEN
      RAISE EXCEPTION 'Only an administrator can change administrator roles'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status
       OR NEW.verified IS DISTINCT FROM OLD.verified
       OR NEW.email IS DISTINCT FROM OLD.email
       OR NEW.id IS DISTINCT FROM OLD.id THEN
      RAISE EXCEPTION 'Only an administrator can change account status, verification or email'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION staging_private.guard_profile_privileges() FROM PUBLIC;

DROP TRIGGER IF EXISTS guard_profile_privileges ON staging.profiles;
CREATE TRIGGER guard_profile_privileges
  BEFORE INSERT OR UPDATE ON staging.profiles
  FOR EACH ROW EXECUTE FUNCTION staging_private.guard_profile_privileges();

-- 2. No member-wide profile reads ------------------------------------
DROP POLICY IF EXISTS "authenticated users can view all profiles" ON staging.profiles;

-- 3. Anonymous visitors get no table access --------------------------
REVOKE ALL ON ALL TABLES IN SCHEMA staging FROM anon;

-- 4. Image backup tables: service role only --------------------------
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['_backup_20261024_posts_images',
                           '_backup_20261024_events_images',
                           '_backup_20261024_marketplace_items_images'] LOOP
    IF to_regclass('staging.' || t) IS NOT NULL THEN
      EXECUTE format('ALTER TABLE staging.%I ENABLE ROW LEVEL SECURITY', t);
      EXECUTE format('REVOKE ALL ON staging.%I FROM anon, authenticated', t);
    END IF;
  END LOOP;
END $$;

-- 5. Content is always inserted under your own id -----------------------
DROP POLICY IF EXISTS "Enable insert for authenticated users" ON staging.profiles;

DO $$
DECLARE
  pair text[];
BEGIN
  FOREACH pair SLICE 1 IN ARRAY ARRAY[
    ['posts', 'author_id'],
    ['post_comments', 'author_id'],
    ['post_likes', 'user_id'],
    ['post_history', 'edited_by'],
    ['events', 'author_id'],
    ['event_comments', 'author_id'],
    ['event_likes', 'user_id'],
    ['event_rsvps', 'user_id'],
    ['marketplace_items', 'seller_id'],
    ['marketplace_comments', 'author_id'],
    ['marketplace_saves', 'user_id']
  ] LOOP
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_schema = 'staging' AND table_name = pair[1] AND column_name = pair[2]) THEN
      EXECUTE format('DROP POLICY IF EXISTS "Owner: insert as yourself" ON staging.%I', pair[1]);
      EXECUTE format(
        'CREATE POLICY "Owner: insert as yourself" ON staging.%I AS RESTRICTIVE FOR INSERT
           TO authenticated WITH CHECK (%I = (SELECT auth.uid()))', pair[1], pair[2]);
    END IF;
  END LOOP;
END $$;


-- ---------- 20261121000500_reports_moderation.sql ----------
-- =============================================================
-- Reporting + admin moderation for posts, listings, events and their
-- comments.
--
-- Originally written as 20261108000000_post_reports_moderation (posts
-- only, never applied to any database). Generalized here to every
-- content type and renumbered to run after 20261121000400.
--
-- Privacy model:
--   * Nobody reads `reports` / `moderation_actions` directly — RLS is on
--     with no policies, and table grants are revoked. All access goes
--     through the SECURITY DEFINER functions below.
--   * Reporters never see other reports. Admins see the reason, the
--     reporter's free-text details, and a content snapshot — never the
--     reporter's id or the author's id/name/email. Identity reveal stays a
--     separate capability (admin_reveal_post_author / _listing_seller).
--   * The reported author is resolved server-side; the client only sends
--     a content type + id.
--
-- Moderation "hide" uses a RESTRICTIVE select policy on each content
-- table, so it composes with whatever permissive policies already exist
-- there (posts' base policies were created outside the migrations folder).
--
-- Internal helpers live in the staging_private schema, which PostgREST does
-- not expose, so they can't be called from the client.
-- =============================================================

CREATE SCHEMA IF NOT EXISTS staging_private;
REVOKE ALL ON SCHEMA staging_private FROM PUBLIC;
-- Block-visibility helpers (next migration) are evaluated inside RLS
-- policies as the querying role, so that role needs USAGE. EXECUTE is
-- granted per function, never schema-wide.
GRANT USAGE ON SCHEMA staging_private TO authenticated;

-- 1. Tables ---------------------------------------------------------

CREATE TABLE IF NOT EXISTS staging.reports (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  reporter_id      UUID REFERENCES staging.profiles(id) ON DELETE SET NULL,
  target_type      TEXT NOT NULL CHECK (target_type IN (
                     'post', 'post_comment',
                     'marketplace_item', 'marketplace_comment',
                     'event', 'event_comment')),
  -- No FK: the report (and its snapshot) must survive the content being removed.
  target_id        UUID NOT NULL,
  reason           TEXT NOT NULL CHECK (reason IN (
                     'spam', 'harassment', 'hate', 'sexual_content',
                     'violence_or_threat', 'personal_info', 'impersonation', 'other')),
  details          TEXT CHECK (details IS NULL OR char_length(details) <= 500),
  content_snapshot JSONB NOT NULL,
  status           TEXT NOT NULL DEFAULT 'pending'
                     CHECK (status IN ('pending', 'under_review', 'resolved', 'dismissed')),
  action_taken     TEXT CHECK (action_taken IN ('none', 'hidden', 'unhidden', 'removed')),
  moderator_note   TEXT CHECK (moderator_note IS NULL OR char_length(moderator_note) <= 1000),
  reviewed_at      TIMESTAMPTZ,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- One open report per reporter per target; a re-report after the earlier
-- one was closed is allowed.
CREATE UNIQUE INDEX IF NOT EXISTS reports_one_open_per_reporter
  ON staging.reports (reporter_id, target_type, target_id)
  WHERE status IN ('pending', 'under_review');
CREATE INDEX IF NOT EXISTS reports_status_created ON staging.reports (status, created_at DESC);
CREATE INDEX IF NOT EXISTS reports_target ON staging.reports (target_type, target_id);
CREATE INDEX IF NOT EXISTS reports_reporter_created ON staging.reports (reporter_id, created_at DESC);

-- Append-only audit log of moderator decisions.
CREATE TABLE IF NOT EXISTS staging.moderation_actions (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_id    UUID REFERENCES staging.profiles(id) ON DELETE SET NULL,
  action      TEXT NOT NULL,
  target_type TEXT NOT NULL,
  target_id   UUID NOT NULL,
  report_ids  UUID[] NOT NULL DEFAULT '{}',
  status      TEXT,
  note        TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS moderation_actions_target ON staging.moderation_actions (target_type, target_id);

ALTER TABLE staging.reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE staging.moderation_actions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON staging.reports FROM anon, authenticated;
REVOKE ALL ON staging.moderation_actions FROM anon, authenticated;

-- 2. Hiding content -------------------------------------------------
-- The author still sees their own hidden content; admins see everything.

ALTER TABLE staging.posts                ADD COLUMN IF NOT EXISTS hidden_at TIMESTAMPTZ;
ALTER TABLE staging.post_comments        ADD COLUMN IF NOT EXISTS hidden_at TIMESTAMPTZ;
ALTER TABLE staging.marketplace_items    ADD COLUMN IF NOT EXISTS hidden_at TIMESTAMPTZ;
ALTER TABLE staging.marketplace_comments ADD COLUMN IF NOT EXISTS hidden_at TIMESTAMPTZ;
ALTER TABLE staging.events               ADD COLUMN IF NOT EXISTS hidden_at TIMESTAMPTZ;
ALTER TABLE staging.event_comments       ADD COLUMN IF NOT EXISTS hidden_at TIMESTAMPTZ;

DROP POLICY IF EXISTS "Moderation: hide hidden posts" ON staging.posts;
CREATE POLICY "Moderation: hide hidden posts"
  ON staging.posts AS RESTRICTIVE FOR SELECT
  USING (hidden_at IS NULL OR author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin()));

DROP POLICY IF EXISTS "Moderation: hide hidden post comments" ON staging.post_comments;
CREATE POLICY "Moderation: hide hidden post comments"
  ON staging.post_comments AS RESTRICTIVE FOR SELECT
  USING (hidden_at IS NULL OR author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin()));

DROP POLICY IF EXISTS "Moderation: hide hidden listings" ON staging.marketplace_items;
CREATE POLICY "Moderation: hide hidden listings"
  ON staging.marketplace_items AS RESTRICTIVE FOR SELECT
  USING (hidden_at IS NULL OR seller_id = (SELECT auth.uid()) OR (SELECT staging.is_admin()));

DROP POLICY IF EXISTS "Moderation: hide hidden listing comments" ON staging.marketplace_comments;
CREATE POLICY "Moderation: hide hidden listing comments"
  ON staging.marketplace_comments AS RESTRICTIVE FOR SELECT
  USING (hidden_at IS NULL OR author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin()));

DROP POLICY IF EXISTS "Moderation: hide hidden events" ON staging.events;
CREATE POLICY "Moderation: hide hidden events"
  ON staging.events AS RESTRICTIVE FOR SELECT
  USING (hidden_at IS NULL OR author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin()));

DROP POLICY IF EXISTS "Moderation: hide hidden event comments" ON staging.event_comments;
CREATE POLICY "Moderation: hide hidden event comments"
  ON staging.event_comments AS RESTRICTIVE FOR SELECT
  USING (hidden_at IS NULL OR author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin()));

-- Authors may UPDATE their own rows (edit post/listing), which would
-- otherwise let them clear hidden_at and un-hide moderated content.
-- Only admins (directly, or via admin_moderate_reports) may change it.
CREATE OR REPLACE FUNCTION staging_private.guard_hidden_at()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = staging
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.hidden_at := NULL;
  ELSIF NEW.hidden_at IS DISTINCT FROM OLD.hidden_at AND NOT staging.is_admin() THEN
    RAISE EXCEPTION 'hidden_at_admin_only' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['posts', 'post_comments', 'marketplace_items',
                           'marketplace_comments', 'events', 'event_comments'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS guard_hidden_at ON staging.%I', t);
    EXECUTE format('CREATE TRIGGER guard_hidden_at BEFORE INSERT OR UPDATE OF hidden_at ON staging.%I
                    FOR EACH ROW EXECUTE FUNCTION staging_private.guard_hidden_at()', t);
    IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = ('staging.' || t)::regclass) THEN
      RAISE WARNING 'RLS is disabled on staging.%: moderation "hide" and user blocks will have no effect there until it is enabled.', t;
    END IF;
  END LOOP;
END $$;

-- 3. Internal helpers (staging_private, not exposed) --------------------

-- Whitelisted content type -> table name. NULL for anything else.
CREATE OR REPLACE FUNCTION staging_private.content_table(p_type TEXT)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE p_type
    WHEN 'post'                THEN 'posts'
    WHEN 'post_comment'        THEN 'post_comments'
    WHEN 'marketplace_item'    THEN 'marketplace_items'
    WHEN 'marketplace_comment' THEN 'marketplace_comments'
    WHEN 'event'               THEN 'events'
    WHEN 'event_comment'       THEN 'event_comments'
  END
$$;

-- Owner, hidden state and a normalized content snapshot for one piece of
-- content, read without RLS. Zero rows when it doesn't exist. Snapshot
-- keys: title, content, image_url, category, created_at, and for
-- comments parent_id / parent_title.
CREATE OR REPLACE FUNCTION staging_private.content_target(p_type TEXT, p_id UUID)
RETURNS TABLE (owner_id UUID, hidden_at TIMESTAMPTZ, content JSONB)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
BEGIN
  IF p_type = 'post' THEN
    RETURN QUERY
    SELECT p.author_id, p.hidden_at, jsonb_build_object(
             'title', p.title, 'content', p.content, 'image_url', p.image_url,
             'category', p.category, 'created_at', p.created_at)
      FROM staging.posts p WHERE p.id = p_id;
  ELSIF p_type = 'post_comment' THEN
    RETURN QUERY
    SELECT c.author_id, c.hidden_at, jsonb_build_object(
             'content', c.text, 'created_at', c.created_at,
             'parent_id', c.post_id, 'parent_title', p.title)
      FROM staging.post_comments c LEFT JOIN staging.posts p ON p.id = c.post_id
     WHERE c.id = p_id;
  ELSIF p_type = 'marketplace_item' THEN
    RETURN QUERY
    SELECT m.seller_id, m.hidden_at, jsonb_build_object(
             'title', m.title, 'content', m.description,
             'image_url', COALESCE(m.image_url, m.images[1]),
             'category', m.category, 'price', m.price, 'created_at', m.created_at)
      FROM staging.marketplace_items m WHERE m.id = p_id;
  ELSIF p_type = 'marketplace_comment' THEN
    RETURN QUERY
    SELECT c.author_id, c.hidden_at, jsonb_build_object(
             'content', c.text, 'created_at', c.created_at,
             'parent_id', c.item_id, 'parent_title', m.title)
      FROM staging.marketplace_comments c LEFT JOIN staging.marketplace_items m ON m.id = c.item_id
     WHERE c.id = p_id;
  ELSIF p_type = 'event' THEN
    RETURN QUERY
    SELECT e.author_id, e.hidden_at, jsonb_build_object(
             'title', e.title, 'content', e.description, 'image_url', e.image_url,
             'category', e.category, 'event_date', e.date, 'created_at', e.created_at)
      FROM staging.events e WHERE e.id = p_id;
  ELSIF p_type = 'event_comment' THEN
    RETURN QUERY
    SELECT c.author_id, c.hidden_at, jsonb_build_object(
             'content', c.text, 'created_at', c.created_at,
             'parent_id', c.event_id, 'parent_title', e.title)
      FROM staging.event_comments c LEFT JOIN staging.events e ON e.id = c.event_id
     WHERE c.id = p_id;
  END IF;
END;
$$;

-- 4. Reporter RPC ---------------------------------------------------

-- Returns 'created' or 'duplicate'. Raises with a stable message for
-- every rejection so the client can map it to friendly copy.
CREATE OR REPLACE FUNCTION staging.submit_report(
  p_target_type TEXT,
  p_target_id   UUID,
  p_reason      TEXT,
  p_details     TEXT DEFAULT NULL
)
RETURNS TEXT
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = staging
AS $$
DECLARE
  v_uid     UUID := auth.uid();
  v_details TEXT := NULLIF(btrim(p_details), '');
  v_target  RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF staging_private.content_table(p_target_type) IS NULL OR p_target_id IS NULL THEN
    RAISE EXCEPTION 'invalid_target' USING ERRCODE = '22023';
  END IF;

  IF p_reason IS NULL OR p_reason NOT IN (
    'spam', 'harassment', 'hate', 'sexual_content',
    'violence_or_threat', 'personal_info', 'impersonation', 'other'
  ) THEN
    RAISE EXCEPTION 'invalid_reason' USING ERRCODE = '22023';
  END IF;
  IF p_reason = 'other' AND v_details IS NULL THEN
    RAISE EXCEPTION 'details_required' USING ERRCODE = '22023';
  END IF;
  IF char_length(v_details) > 500 THEN
    RAISE EXCEPTION 'details_too_long' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_target FROM staging_private.content_target(p_target_type, p_target_id);
  -- Hidden content is treated as gone for anyone who could not see it.
  IF NOT FOUND OR (v_target.hidden_at IS NOT NULL AND v_target.owner_id <> v_uid AND NOT staging.is_admin()) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_target.owner_id = v_uid THEN
    RAISE EXCEPTION 'cannot_report_own' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM staging.reports
     WHERE reporter_id = v_uid AND target_type = p_target_type AND target_id = p_target_id
       AND status IN ('pending', 'under_review')
  ) THEN
    RETURN 'duplicate';
  END IF;

  IF (SELECT count(*) FROM staging.reports
       WHERE reporter_id = v_uid AND created_at > now() - interval '24 hours') >= 20 THEN
    RAISE EXCEPTION 'rate_limited' USING ERRCODE = '54000';
  END IF;

  BEGIN
    INSERT INTO staging.reports (reporter_id, target_type, target_id, reason, details, content_snapshot)
    VALUES (v_uid, p_target_type, p_target_id, p_reason, v_details, v_target.content);
  EXCEPTION WHEN unique_violation THEN
    -- Double submit that raced past the EXISTS check above.
    RETURN 'duplicate';
  END;

  RETURN 'created';
END;
$$;

-- 5. Admin RPCs -----------------------------------------------------

-- Deliberately omits reporter_id and the content owner's id.
CREATE OR REPLACE FUNCTION staging.admin_list_reports(p_status TEXT DEFAULT NULL)
RETURNS TABLE (
  id               UUID,
  target_type      TEXT,
  target_id        UUID,
  reason           TEXT,
  details          TEXT,
  status           TEXT,
  action_taken     TEXT,
  moderator_note   TEXT,
  reviewed_at      TIMESTAMPTZ,
  created_at       TIMESTAMPTZ,
  content_snapshot JSONB,
  target_exists    BOOLEAN,
  target_hidden    BOOLEAN,
  live_content     JSONB
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
BEGIN
  IF NOT staging.is_admin() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT r.id, r.target_type, r.target_id, r.reason, r.details, r.status, r.action_taken,
         r.moderator_note, r.reviewed_at, r.created_at, r.content_snapshot,
         (t.content IS NOT NULL),
         (t.hidden_at IS NOT NULL),
         t.content
    FROM staging.reports r
    LEFT JOIN LATERAL staging_private.content_target(r.target_type, r.target_id) t ON TRUE
   WHERE p_status IS NULL OR r.status = p_status
   ORDER BY r.created_at DESC
   LIMIT 500;
END;
$$;

-- Applies one decision to a group of reports about the same content:
-- a status change, optionally with a content action, plus an audit row.
CREATE OR REPLACE FUNCTION staging.admin_moderate_reports(
  p_report_ids UUID[],
  p_status     TEXT,
  p_action     TEXT DEFAULT 'none',
  p_note       TEXT DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = staging
AS $$
DECLARE
  v_targets   TEXT[];
  v_type      TEXT;
  v_target    UUID;
  v_table     TEXT;
  v_note      TEXT := NULLIF(btrim(p_note), '');
  v_action    TEXT := COALESCE(p_action, 'none');
  v_taken     TEXT;
BEGIN
  IF NOT staging.is_admin() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_report_ids IS NULL OR cardinality(p_report_ids) = 0 THEN
    RAISE EXCEPTION 'no_reports' USING ERRCODE = '22023';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('pending', 'under_review', 'resolved', 'dismissed') THEN
    RAISE EXCEPTION 'invalid_status' USING ERRCODE = '22023';
  END IF;
  IF v_action NOT IN ('none', 'hide', 'unhide', 'remove') THEN
    RAISE EXCEPTION 'invalid_action' USING ERRCODE = '22023';
  END IF;
  IF char_length(v_note) > 1000 THEN
    RAISE EXCEPTION 'note_too_long' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(DISTINCT r.target_type || ':' || r.target_id) INTO v_targets
    FROM staging.reports r
   WHERE r.id = ANY (p_report_ids);
  IF v_targets IS NULL
     OR cardinality(v_targets) <> 1
     OR (SELECT count(*) FROM staging.reports WHERE id = ANY (p_report_ids)) <> cardinality(p_report_ids) THEN
    RAISE EXCEPTION 'reports_must_share_one_target' USING ERRCODE = '22023';
  END IF;
  SELECT r.target_type, r.target_id INTO v_type, v_target
    FROM staging.reports r WHERE r.id = p_report_ids[1];
  v_table := staging_private.content_table(v_type);

  -- v_table comes from the whitelist above, never from the caller.
  IF v_action = 'hide' THEN
    EXECUTE format('UPDATE staging.%I SET hidden_at = now() WHERE id = $1 AND hidden_at IS NULL', v_table)
      USING v_target;
    v_taken := 'hidden';
  ELSIF v_action = 'unhide' THEN
    EXECUTE format('UPDATE staging.%I SET hidden_at = NULL WHERE id = $1', v_table) USING v_target;
    v_taken := 'unhidden';
  ELSIF v_action = 'remove' THEN
    -- The report keeps its content_snapshot as the record of what was removed.
    EXECUTE format('DELETE FROM staging.%I WHERE id = $1', v_table) USING v_target;
    v_taken := 'removed';
  END IF;

  UPDATE staging.reports
     SET status         = p_status,
         action_taken   = COALESCE(v_taken, CASE WHEN p_status IN ('resolved', 'dismissed') THEN COALESCE(action_taken, 'none') END, action_taken),
         moderator_note = COALESCE(v_note, moderator_note),
         reviewed_at    = CASE WHEN p_status IN ('resolved', 'dismissed') THEN now() ELSE reviewed_at END,
         updated_at     = now()
   WHERE id = ANY (p_report_ids);

  INSERT INTO staging.moderation_actions (actor_id, action, target_type, target_id, report_ids, status, note)
  VALUES (auth.uid(), v_action, v_type, v_target, p_report_ids, p_status, v_note);
END;
$$;

-- 6. Grants ---------------------------------------------------------

-- Internal only: called from the SECURITY DEFINER functions here, never by
-- client roles. (Named individually so a re-run can't revoke grants that
-- later migrations give to other staging_private functions.)
REVOKE ALL ON FUNCTION staging_private.content_table(TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION staging_private.content_target(TEXT, UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION staging_private.guard_hidden_at() FROM PUBLIC, anon, authenticated;

REVOKE ALL ON FUNCTION staging.submit_report(TEXT, UUID, TEXT, TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION staging.admin_list_reports(TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION staging.admin_moderate_reports(UUID[], TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION staging.submit_report(TEXT, UUID, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION staging.admin_list_reports(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION staging.admin_moderate_reports(UUID[], TEXT, TEXT, TEXT) TO authenticated;

NOTIFY pgrst, 'reload schema';


-- ---------- 20261121000600_user_blocks.sql ----------
-- =============================================================
-- User blocking MVP (spec: docs/week1-reporting-blocking-spec.md §2–3,
-- policy: docs/reporting-blocking-mvp.md).
--
-- Policy — when A blocks B (symmetric; either direction counts):
--   * Neither sees the other's posts, listings, events or comments.
--   * Neither can like, comment on, save or RSVP to the other's content.
--   * Neither can start a new conversation with the other, and no new
--     messages can be sent in an existing one (history stays readable).
--   * Your own content is always visible to you; admins are exempt so
--     moderation keeps working.
--   * B is never told. Blocks are keyed on internal user ids, but the
--     client never sends or receives one: it names a piece of content and
--     the server resolves its author.
--
-- Depends on staging_private.content_target from 20261121000500.
-- =============================================================

-- 1. Table ----------------------------------------------------------

CREATE TABLE IF NOT EXISTS staging.user_blocks (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  blocker_id   UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  blocked_id   UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  -- Where the block was made from, and the alias shown there — aliases are
  -- per item, so this is the only name the blocker ever saw for them.
  source_type  TEXT NOT NULL CHECK (source_type IN (
                 'post', 'post_comment',
                 'marketplace_item', 'marketplace_comment',
                 'event', 'event_comment')),
  source_alias TEXT CHECK (source_alias IS NULL OR char_length(source_alias) <= 80),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT user_blocks_not_self CHECK (blocker_id <> blocked_id),
  CONSTRAINT user_blocks_pair_unique UNIQUE (blocker_id, blocked_id)
);
CREATE INDEX IF NOT EXISTS user_blocks_blocked ON staging.user_blocks (blocked_id);

ALTER TABLE staging.user_blocks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON staging.user_blocks FROM anon, authenticated;

-- 2. Helpers used inside RLS (staging_private, not exposed) -------------
-- SECURITY DEFINER so policies can consult user_blocks, which the
-- querying role can't read.

-- Everyone the current user has blocked or been blocked by.
CREATE OR REPLACE FUNCTION staging_private.block_peer_ids()
RETURNS UUID[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
  SELECT COALESCE(array_agg(peer), '{}')
    FROM (
      SELECT blocked_id AS peer FROM staging.user_blocks WHERE blocker_id = auth.uid()
      UNION
      SELECT blocker_id FROM staging.user_blocks WHERE blocked_id = auth.uid()
    ) s
$$;

CREATE OR REPLACE FUNCTION staging_private.is_block_peer(p_user UUID)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
  SELECT p_user IS NOT NULL AND EXISTS (
    SELECT 1 FROM staging.user_blocks
     WHERE (blocker_id = auth.uid() AND blocked_id = p_user)
        OR (blocker_id = p_user AND blocked_id = auth.uid())
  )
$$;

-- Owner of a parent item, even if the caller can no longer see it.
CREATE OR REPLACE FUNCTION staging_private.content_owner(p_type TEXT, p_id UUID)
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
  SELECT owner_id FROM staging_private.content_target(p_type, p_id)
$$;

CREATE OR REPLACE FUNCTION staging_private.conversation_has_block_peer(p_conversation_id UUID)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
  SELECT EXISTS (
    SELECT 1 FROM staging.conversation_participants cp
     WHERE cp.conversation_id = p_conversation_id
       AND cp.user_id <> auth.uid()
       AND staging_private.is_block_peer(cp.user_id)
  )
$$;

REVOKE ALL ON FUNCTION staging_private.block_peer_ids() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION staging_private.is_block_peer(UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION staging_private.content_owner(TEXT, UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION staging_private.conversation_has_block_peer(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION staging_private.block_peer_ids() TO authenticated;
GRANT EXECUTE ON FUNCTION staging_private.is_block_peer(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION staging_private.content_owner(TEXT, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION staging_private.conversation_has_block_peer(UUID) TO authenticated;

-- 3. Visibility (RESTRICTIVE: ANDs with the existing SELECT policies) -
-- The scalar `(SELECT ...)` makes Postgres evaluate the peer list once per
-- query (an InitPlan) instead of once per row.

DROP POLICY IF EXISTS "Blocks: hide blocked authors" ON staging.posts;
CREATE POLICY "Blocks: hide blocked authors"
  ON staging.posts AS RESTRICTIVE FOR SELECT
  USING (author_id IS NULL OR author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin())
         OR NOT (author_id = ANY (COALESCE((SELECT staging_private.block_peer_ids()), '{}'))));

DROP POLICY IF EXISTS "Blocks: hide blocked authors" ON staging.post_comments;
CREATE POLICY "Blocks: hide blocked authors"
  ON staging.post_comments AS RESTRICTIVE FOR SELECT
  USING (author_id IS NULL OR author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin())
         OR NOT (author_id = ANY (COALESCE((SELECT staging_private.block_peer_ids()), '{}'))));

DROP POLICY IF EXISTS "Blocks: hide blocked sellers" ON staging.marketplace_items;
CREATE POLICY "Blocks: hide blocked sellers"
  ON staging.marketplace_items AS RESTRICTIVE FOR SELECT
  USING (seller_id = (SELECT auth.uid()) OR (SELECT staging.is_admin())
         OR NOT (seller_id = ANY (COALESCE((SELECT staging_private.block_peer_ids()), '{}'))));

DROP POLICY IF EXISTS "Blocks: hide blocked authors" ON staging.marketplace_comments;
CREATE POLICY "Blocks: hide blocked authors"
  ON staging.marketplace_comments AS RESTRICTIVE FOR SELECT
  USING (author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin())
         OR NOT (author_id = ANY (COALESCE((SELECT staging_private.block_peer_ids()), '{}'))));

DROP POLICY IF EXISTS "Blocks: hide blocked authors" ON staging.events;
CREATE POLICY "Blocks: hide blocked authors"
  ON staging.events AS RESTRICTIVE FOR SELECT
  USING (author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin())
         OR NOT (author_id = ANY (COALESCE((SELECT staging_private.block_peer_ids()), '{}'))));

DROP POLICY IF EXISTS "Blocks: hide blocked authors" ON staging.event_comments;
CREATE POLICY "Blocks: hide blocked authors"
  ON staging.event_comments AS RESTRICTIVE FOR SELECT
  USING (author_id = (SELECT auth.uid()) OR (SELECT staging.is_admin())
         OR NOT (author_id = ANY (COALESCE((SELECT staging_private.block_peer_ids()), '{}'))));

-- 4. Interactions (RESTRICTIVE INSERT) ------------------------------

DROP POLICY IF EXISTS "Blocks: no likes across a block" ON staging.post_likes;
CREATE POLICY "Blocks: no likes across a block"
  ON staging.post_likes AS RESTRICTIVE FOR INSERT
  WITH CHECK (NOT staging_private.is_block_peer(staging_private.content_owner('post', post_id)));

DROP POLICY IF EXISTS "Blocks: no comments across a block" ON staging.post_comments;
CREATE POLICY "Blocks: no comments across a block"
  ON staging.post_comments AS RESTRICTIVE FOR INSERT
  WITH CHECK (NOT staging_private.is_block_peer(staging_private.content_owner('post', post_id)));

DROP POLICY IF EXISTS "Blocks: no saves across a block" ON staging.marketplace_saves;
CREATE POLICY "Blocks: no saves across a block"
  ON staging.marketplace_saves AS RESTRICTIVE FOR INSERT
  WITH CHECK (NOT staging_private.is_block_peer(staging_private.content_owner('marketplace_item', item_id)));

DROP POLICY IF EXISTS "Blocks: no comments across a block" ON staging.marketplace_comments;
CREATE POLICY "Blocks: no comments across a block"
  ON staging.marketplace_comments AS RESTRICTIVE FOR INSERT
  WITH CHECK (NOT staging_private.is_block_peer(staging_private.content_owner('marketplace_item', item_id)));

DROP POLICY IF EXISTS "Blocks: no likes across a block" ON staging.event_likes;
CREATE POLICY "Blocks: no likes across a block"
  ON staging.event_likes AS RESTRICTIVE FOR INSERT
  WITH CHECK (NOT staging_private.is_block_peer(staging_private.content_owner('event', event_id)));

DROP POLICY IF EXISTS "Blocks: no RSVPs across a block" ON staging.event_rsvps;
CREATE POLICY "Blocks: no RSVPs across a block"
  ON staging.event_rsvps AS RESTRICTIVE FOR INSERT
  WITH CHECK (NOT staging_private.is_block_peer(staging_private.content_owner('event', event_id)));

DROP POLICY IF EXISTS "Blocks: no comments across a block" ON staging.event_comments;
CREATE POLICY "Blocks: no comments across a block"
  ON staging.event_comments AS RESTRICTIVE FOR INSERT
  WITH CHECK (NOT staging_private.is_block_peer(staging_private.content_owner('event', event_id)));

-- New conversations: you can't add a block peer as a participant.
DROP POLICY IF EXISTS "Blocks: no conversations across a block" ON staging.conversation_participants;
CREATE POLICY "Blocks: no conversations across a block"
  ON staging.conversation_participants AS RESTRICTIVE FOR INSERT
  WITH CHECK (NOT staging_private.is_block_peer(user_id));

-- Existing conversations become read-only.
DROP POLICY IF EXISTS "Blocks: no messages across a block" ON staging.messages;
CREATE POLICY "Blocks: no messages across a block"
  ON staging.messages AS RESTRICTIVE FOR INSERT
  WITH CHECK (NOT staging_private.conversation_has_block_peer(conversation_id));

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['post_likes', 'marketplace_saves', 'event_likes', 'event_rsvps',
                           'conversation_participants', 'messages'] LOOP
    IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = ('staging.' || t)::regclass) THEN
      RAISE WARNING 'RLS is disabled on staging.%: block interaction rules will have no effect there until it is enabled.', t;
    END IF;
  END LOOP;
END $$;

-- 5. RPCs -----------------------------------------------------------

-- Blocks whoever wrote the given content. Returns 'blocked' or
-- 'already_blocked'; never returns the blocked user's id.
CREATE OR REPLACE FUNCTION staging.block_author_of(
  p_target_type  TEXT,
  p_target_id    UUID,
  p_source_alias TEXT DEFAULT NULL
)
RETURNS TEXT
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = staging
AS $$
DECLARE
  v_uid   UUID := auth.uid();
  v_owner UUID;
  v_alias TEXT := left(NULLIF(btrim(p_source_alias), ''), 80);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF staging_private.content_table(p_target_type) IS NULL OR p_target_id IS NULL THEN
    RAISE EXCEPTION 'invalid_target' USING ERRCODE = '22023';
  END IF;

  v_owner := staging_private.content_owner(p_target_type, p_target_id);
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_owner = v_uid THEN
    RAISE EXCEPTION 'cannot_block_self' USING ERRCODE = '22023';
  END IF;

  IF (SELECT count(*) FROM staging.user_blocks WHERE blocker_id = v_uid) >= 1000 THEN
    RAISE EXCEPTION 'too_many_blocks' USING ERRCODE = '54000';
  END IF;

  INSERT INTO staging.user_blocks (blocker_id, blocked_id, source_type, source_alias)
  VALUES (v_uid, v_owner, p_target_type, v_alias)
  ON CONFLICT (blocker_id, blocked_id) DO NOTHING;

  RETURN CASE WHEN FOUND THEN 'blocked' ELSE 'already_blocked' END;
END;
$$;

-- The caller's own blocks, newest first — alias and date only.
CREATE OR REPLACE FUNCTION staging.list_my_blocks()
RETURNS TABLE (id UUID, source_type TEXT, source_alias TEXT, created_at TIMESTAMPTZ)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
  SELECT b.id, b.source_type, b.source_alias, b.created_at
    FROM staging.user_blocks b
   WHERE b.blocker_id = auth.uid()
   ORDER BY b.created_at DESC
$$;

-- Removes one of the caller's own blocks. Returns false if it wasn't theirs
-- or no longer exists.
CREATE OR REPLACE FUNCTION staging.unblock(p_block_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = staging
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  DELETE FROM staging.user_blocks WHERE id = p_block_id AND blocker_id = auth.uid();
  RETURN FOUND;
END;
$$;

REVOKE ALL ON FUNCTION staging.block_author_of(TEXT, UUID, TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION staging.list_my_blocks() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION staging.unblock(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION staging.block_author_of(TEXT, UUID, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION staging.list_my_blocks() TO authenticated;
GRANT EXECUTE ON FUNCTION staging.unblock(UUID) TO authenticated;

NOTIFY pgrst, 'reload schema';


-- ---------- 20261121000700_admin_dashboard.sql ----------
-- =============================================================
-- Admin dashboard read models: report counts, per-item moderation
-- history, and aggregate blocking statistics. All three are
-- read-only, admin-only (is_admin() checked inside), and return no
-- user ids, names or emails.
--
-- Depends on 20261121000500 (reports, moderation_actions,
-- staging_private.content_owner via 000600) and 20261121000600 (user_blocks).
-- =============================================================

-- Counts for the dashboard summary cards and the Reports tab badge,
-- without downloading the queue itself.
CREATE OR REPLACE FUNCTION staging.admin_report_counts()
RETURNS TABLE (status TEXT, target_type TEXT, report_count BIGINT)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
BEGIN
  IF NOT staging.is_admin() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT r.status, r.target_type, count(*)
    FROM staging.reports r
   GROUP BY r.status, r.target_type;
END;
$$;

-- Audit trail for one piece of content. `by_me` replaces the acting
-- admin's id so the history doesn't become an admin directory.
CREATE OR REPLACE FUNCTION staging.admin_list_moderation_actions(
  p_target_type TEXT,
  p_target_id   UUID
)
RETURNS TABLE (
  id           UUID,
  action       TEXT,
  status       TEXT,
  note         TEXT,
  report_count INT,
  created_at   TIMESTAMPTZ,
  by_me        BOOLEAN
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
BEGIN
  IF NOT staging.is_admin() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT m.id, m.action, m.status, m.note, cardinality(m.report_ids), m.created_at,
         (m.actor_id = auth.uid())
    FROM staging.moderation_actions m
   WHERE m.target_type = p_target_type AND m.target_id = p_target_id
   ORDER BY m.created_at DESC
   LIMIT 100;
END;
$$;

-- Aggregate-only view of blocking. Deliberately never returns who blocked
-- whom; "repeatedly blocked" and "blocked while reported" are counts of
-- accounts, not lists, so they flag that something needs attention
-- without exposing relationships.
CREATE OR REPLACE FUNCTION staging.admin_block_stats()
RETURNS TABLE (
  total_blocks                  BIGINT,
  blocks_last_7_days            BIGINT,
  blocks_last_30_days           BIGINT,
  accounts_blocking             BIGINT,
  accounts_blocked              BIGINT,
  accounts_blocked_by_3_plus    BIGINT,
  blocked_with_open_reports     BIGINT,
  by_source                     JSONB
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
BEGIN
  IF NOT staging.is_admin() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  WITH open_report_owners AS (
    SELECT DISTINCT staging_private.content_owner(r.target_type, r.target_id) AS owner_id
      FROM staging.reports r
     WHERE r.status IN ('pending', 'under_review')
  )
  SELECT
    (SELECT count(*) FROM staging.user_blocks),
    (SELECT count(*) FROM staging.user_blocks WHERE created_at > now() - interval '7 days'),
    (SELECT count(*) FROM staging.user_blocks WHERE created_at > now() - interval '30 days'),
    (SELECT count(DISTINCT blocker_id) FROM staging.user_blocks),
    (SELECT count(DISTINCT blocked_id) FROM staging.user_blocks),
    (SELECT count(*) FROM (
       SELECT blocked_id FROM staging.user_blocks GROUP BY blocked_id HAVING count(*) >= 3
     ) s),
    (SELECT count(DISTINCT b.blocked_id) FROM staging.user_blocks b
      WHERE b.blocked_id IN (SELECT owner_id FROM open_report_owners)),
    COALESCE((SELECT jsonb_object_agg(source_type, n)
                FROM (SELECT source_type, count(*) AS n FROM staging.user_blocks GROUP BY source_type) s),
             '{}'::jsonb);
END;
$$;

REVOKE ALL ON FUNCTION staging.admin_report_counts() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION staging.admin_list_moderation_actions(TEXT, UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION staging.admin_block_stats() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION staging.admin_report_counts() TO authenticated;
GRANT EXECUTE ON FUNCTION staging.admin_list_moderation_actions(TEXT, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION staging.admin_block_stats() TO authenticated;

NOTIFY pgrst, 'reload schema';


-- =============================================================
-- Gate: staging is for seeded test accounts only.
-- The API exposes staging to every signed-in production user, so every
-- staging table gets a RESTRICTIVE policy: you must have a
-- staging.profiles row, and only SQL (staging_seed.sql) creates those.
-- =============================================================
CREATE FUNCTION staging_private.is_staging_member()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = staging
AS $$
  SELECT EXISTS (SELECT 1 FROM staging.profiles WHERE id = (SELECT auth.uid()));
$$;
REVOKE ALL ON FUNCTION staging_private.is_staging_member() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION staging_private.is_staging_member() TO authenticated;

-- No self-enrolment: drop every client INSERT policy on staging.profiles.
DO $$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies
           WHERE schemaname = 'staging' AND tablename = 'profiles' AND cmd = 'INSERT' LOOP
    EXECUTE format('DROP POLICY %I ON staging.profiles', p.policyname);
  END LOOP;
END $$;

DO $$
DECLARE t record;
BEGIN
  FOR t IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
           WHERE n.nspname = 'staging' AND c.relkind = 'r' LOOP
    EXECUTE format('ALTER TABLE staging.%I ENABLE ROW LEVEL SECURITY', t.relname);
    EXECUTE format(
      'CREATE POLICY "Staging: test accounts only" ON staging.%I AS RESTRICTIVE FOR ALL
         TO authenticated USING ((SELECT staging_private.is_staging_member()))
         WITH CHECK ((SELECT staging_private.is_staging_member()))', t.relname);
  END LOOP;
END $$;

-- anon never needs staging tables (the hotfix copy already revoked them;
-- repeated here so the gate holds even if that changes).
REVOKE ALL ON ALL TABLES IN SCHEMA staging FROM anon;

COMMIT;

-- Optional, separate step (shared Realtime publication; needs approval):
--   ALTER PUBLICATION supabase_realtime ADD TABLE staging.messages;
